│  │  └─ battery.js           // ব্যাটারি (12 V 7Ah/9Ah SLA)‑এর স্বাস্থ্য পরীক্ষা
│  ├─ services/
│  │  ├─ eventBus.js          // একক Event‑Bus (Node.js EventEmitter)
│  │  ├─ network.js           // MQTT/HTTP‑এর মাধ্যমে ডেটা পাঠানো
│  │  └─ ui.js                // Express‑ভিত্তিক রিয়েল‑টাইম UI
│  └─ main.js                 // মেইন এন্ট্রি, সব মডিউল যুক্ত করা
├─ package.json
