## ১. `src/sensors/zmpt101b.js`

```js
'use strict';
/**
 * ZMPT101B AC‑সেন্সর থেকে ভোল্টেজ পড়ার মডিউল
 *  - ADC (ESP32 / Raspberry‑Pi Pico) থেকে 12‑bit রিড
 *  - 0‑3.3 V → 0‑230 V AC (স্কেল ফ্যাক্টর 70)
 *  - Zero‑crossing detection এর জন্য optocoupler ব্যবহার
 *  - রিয়েল‑টাইমে Event‑Bus‑এ 'acVoltage' ইভেন্ট পাঠায়
 */

const { EventEmitter } = require('events');
const { readADC } = require('../utils/adc'); // 12‑bit ADC রিডার
const eventBus = new EventEmitter();

const SCALING_FACTOR = 70; // 3.3 V → 230 V

/**
 * AC ভোল্টেজ পড়া ও ইভেন্টে পাঠানো
 * @param {number} adcValue 0‑4095
 */
function processADC(adcValue) {
  const voltage = (adcValue / 4095) * 3.3;          // 0‑3.3 V
  const acVoltage = voltage * SCALING_FACTOR;       // 0‑230 V
  eventBus.emit('acVoltage', { acVoltage, timestamp: Date.now() });
}

/**
 * রিয়েল‑টাইমে ADC পড়া (ইভেন্ট‑ভিত্তিক)
 *  - readADC() একটি Promise রিটার্ন করে
 */
async function start() {
  try {
    const adcValue = await readADC(); // 12‑bit ADC রিড
    processADC(adcValue);
  } catch (err) {
    eventBus.emit('error', { module: 'ZMPT101B', err });
  }
}

module.exports = { start, eventBus };
```

