 *    একই প্রক্রিয়া পুনরাবৃত্তি করে – পোলিং‑টাইমার না ব্যবহার করে রিয়েল‑টাইম হুক।
 *
 * ব্যবহার:
 *   node refresh-modules.js [--dir <path>] [--ext <.js|.ts|...>]
 *
 *   উদা: node refresh-modules.js --dir "K:\Jarvis_Core\00_ENGINE" --ext .js
 */

const fs   = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// ---------- ১. CLI প্যারামিটার পার্স ----------
const argv = require('minimist')(process.argv.slice(2), {
  string: ['dir', 'ext'],
  alias:  { d: 'dir', e: 'ext' },
  default: {
    dir: 'K:\\Jarvis_Core\\00_ENGINE',
    ext: '.js'
  }
});

const TARGET_DIR = path.resolve(argv.dir);
const TARGET_EXT = argv.ext.toLowerCase();

// ---------- ২. ইউটিলিটি: মডিউল রিফ্রেশ ----------
function refreshFile(filePath) {
  const resolved = require.resolve(filePath);
  if (require.cache[resolved]) {
    delete require.cache[resolved];
    console.log(`[CACHE CLEARED] ${filePath}`);
  }
  try {
    require(filePath);
    console.log(`[RELOADED]      ${filePath}`);
  } catch (e) {
    console.error(`[FAILED]       ${filePath}\n   ${e.stack}`);
  }
}

// ---------- ৩. একবারের ব্যাচ রিফ্রেশ ----------
function batchRefresh() {
  let entries;
  try {
    entries = fs.readdirSync(TARGET_DIR, { withFileTypes: true });
  } catch (e) {
  console.error(`ডিরেক্টরি পড়তে ব্যর্থ: ${TARGET_DIR}\n${e}`);
    process.exit(1);
  }

  entries.forEach(entry => {
    if (!entry.isFile()) return;
    if (path.extname(entry.name).toLowerCase() !== TARGET_EXT) return;

    const fullPath = path.join(TARGET_DIR, entry.name);
    refreshFile(fullPath);
  });
}

// ---------- ৪. রিয়েল‑টাইম ফাইল‑ওয়াচ (ইভেন্ট‑হুক) ----------
function startWatcher() {
  console.log(`🛎️  Watching ${TARGET_DIR} for *${TARGET_EXT} changes…`);
  const watcher = fs.watch(TARGET_DIR, { persistent: true }, (event, filename) => {
    if (!filename) return; // কিছু OS‑এ filename না আসতে পারে
    if (path.extname(filename).toLowerCase() !== TARGET_EXT) return;

    const fullPath = path.join(TARGET_DIR, filename);
    // ফাইল সেভের পর OS‑এ “rename” অথবা “change” ইভেন্ট আসতে পারে,
    // তাই ছোট ডিলে দিয়ে নিশ্চিত করা হয় ফাইলটি সত্যিই রিড‑যোগ্য।
    setTimeout(() => {
      if (fs.existsSync(fullPath)) {
        refreshFile(fullPath);
      } else {
        // ফাইল ডিলিট হলে ক্যাশ থেকে সরিয়ে ফেলি
        const resolved = require.resolve(fullPath);
        if (require.cache[resolved]) {
          delete require.cache[resolved];
          console.log(`[DELETED] Cache cleared for ${fullPath}`);
        }
      }
    }, 50); // ৫০ ms ডিলে – পোলিং না, একবারের ডিলে
  });

  // প্রক্রিয়া বন্ধ হলে ওয়াচার বন্ধ করা নিশ্চিত করুন
  process.on('SIGINT', () => {
    watcher.close();
    console.log('\n🛑 Watcher stopped. Exiting.');
    process.exit(0);
  });
}

// ---------- ৫. এক্সিকিউশন ----------
batchRefresh();   // স্টার্ট‑আপে একবার চালান (সিঙ্ক্রোনাস)
startWatcher();   // তারপর রিয়েল‑টাইমে হট‑রিলোড চালু রাখুন
