### ১. স্ক্রিপ্ট (refresh‑extensions.js)

```js
'use strict';
const fs   = require('fs');
const path = require('path');

// ১. টার্গেট ডিরেক্টরি
const TARGET_DIR = 'K:\\Jarvis_Core\\00_ENGINE';

// ২. রিফ্রেশ করতে চাওয়া এক্সটেনশন (ডিফল্টে .js)
const TARGET_EXT = '.js';

// ৩. ডিরেক্টরি পড়া
let files;
try {
  files = fs.readdirSync(TARGET_DIR);
} catch (err) {
  console.error(`ডিরেক্টরি পড়তে ব্যর্থ: ${TARGET_DIR}\n${err}`);
  process.exit(1);
}

// ৪. ফিল্টার ও রিফ্রেশ
files.forEach(file => {
  if (path.extname(file).toLowerCase() !== TARGET_EXT) return;

  const fullPath = path.join(TARGET_DIR, file);
  const resolvedPath = require.resolve(fullPath);

  // ক্যাশ মুছে ফেলা
  if (require.cache[resolvedPath]) {
    delete require.cache[resolvedPath];
    console.log(`ক্যাশ মুছে ফেলা: ${file}`);
  }

  // পুনরায় লোড
  try {
    require(fullPath);
    console.log(`রিলোড সফল: ${file}`);
  } catch (e) {
    console.error(`রিলোড ব্যর্থ: ${file}\n${e}`);
  }
});

console.log('সমস্ত টার্গেট ফাইল রিফ্রেশ সম্পন্ন।');
```

